"use strict";class ServiceWorkerSetup{constructor(){if("serviceWorker"in navigator){window.addEventListener('load',()=>{this.registerServiceWorker();});}else{console.warn("Service workers are not supported by this browser");}}registerServiceWorker(){navigator.serviceWorker.register("/sw.js",{scope:'./'}).then(registration=>{console.log("ServiceWorker registration successful with scope:",registration.scope);if(!navigator.serviceWorker.controller)return;if(registration.waiting){this.updateServiceWorker(registration.waiting);return;}if(registration.installing){this.trackInstallingWorker(registration.installing);return;}registration.addEventListener('updatefound',()=>{this.trackInstallingWorker(registration.installing);});}).catch(error=>{console.error("ServiceWorker registration failed:",error);});let refreshing;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;window.location.reload();refreshing=true;});}updateServiceWorker(worker){worker.postMessage({action:'skipWaiting'});}trackInstallingWorker(worker){worker.addEventListener('statechange',()=>{if(worker.state==='installed'){this.updateServiceWorker(worker);}});}}window.serviceWorkerSetup=new ServiceWorkerSetup();